 'use strict';
// UI visibility is convenience only. Every server command verifies signed Telegram identity.
(()=>{
 if(!OrbitaCloud.enabled||String(OrbitaCloud.identity)!=='6088315974')return;
 const nav=document.querySelector('nav'),button=document.createElement('button');button.dataset.page='admin';button.innerHTML='<span>⚙</span>Админ-панель';nav.append(button);nav.classList.add('with-admin');
 const section=document.createElement('section');section.id='admin';section.className='page hidden';
 section.innerHTML=`<div class="section-title"><div><span class="kicker">УПРАВЛЕНИЕ / SPACERACING</span><h1>Админ-панель</h1></div></div><p id="adminStatus" role="status">Подключаем сервер…</p><section class="panel"><span class="kicker">ТЕКУЩИЙ КОНКУРС</span><h2 id="adminTime">—</h2><p id="adminContestId" class="muted"></p><div class="admin-summary" id="adminSummary"></div><label class="admin-duration">Количество времени <input id="adminMinutes" type="number" min="1" max="525600" step="1" value="60"><select id="adminUnit" aria-label="Единица времени"><option value="1">минут</option><option value="60">часов</option><option value="1440">дней</option></select></label><div class="admin-actions"><button class="secondary" data-admin="set">Задать остаток</button><button class="secondary" data-admin="add">Добавить время</button><button class="secondary" data-admin="subtract">Уменьшить время</button><button class="secondary" data-admin="pause">Пауза</button><button class="secondary" data-admin="resume">Продолжить</button><button class="secondary" data-admin="finish">Завершить конкурс</button><button class="primary" data-admin="new">Запустить новый конкурс</button></div><p class="muted">Новый конкурс обнуляет только сумму метров в рейтинге. Монеты, корабли и улучшения сохраняются. Полёт, не сохранённый до паузы или завершения, учитывается как тренировочный.</p><div class="admin-actions"><button class="secondary" id="adminRefresh">Обновить</button><button class="secondary hidden" id="adminRetry">Повторить сохранение</button></div></section><section class="panel"><h2>Текущий топ по дальности</h2><div class="table-wrap"><table><thead><tr><th>Место</th><th>Никнейм</th><th>Telegram ID</th><th>Дальность</th></tr></thead><tbody id="adminRanking"></tbody></table></div></section><section class="panel"><h2>История конкурсов</h2><p class="muted">Архивные результаты остаются в Google-таблице.</p><div id="adminHistory"></div></section><section class="panel"><h2>Действия администратора</h2><div id="adminLog"></div></section>`;
 document.querySelector('main').append(section);
 let snapshot=null,busy=false,pending=null,offset=0;const storageKey='spaceracing-admin-command-'+OrbitaCloud.identity;
 const names={new:'Новый конкурс',set:'Изменено оставшееся время',add:'Добавлено время',subtract:'Уменьшено время',pause:'Пауза',resume:'Продолжение',finish:'Завершение'};
 try{pending=JSON.parse(localStorage.getItem(storageKey));}catch{}
 const text=(selector,value)=>{section.querySelector(selector).textContent=value;};
 function controls(){section.querySelectorAll('[data-admin]').forEach(b=>{const status=snapshot?.season.status;const op=b.dataset.admin;b.disabled=busy||!!pending||!snapshot||(op==='resume'&&status!=='paused')||(op==='pause'&&status!=='running')||(!['new','finish'].includes(op)&&['finished','idle'].includes(status));});$('#adminMinutes').disabled=busy||!!pending||!snapshot;$('#adminUnit').disabled=busy||!!pending||!snapshot;$('#adminRefresh').disabled=busy;$('#adminRetry').classList.toggle('hidden',!pending);$('#adminRetry').disabled=busy;}
 function clock(){if(!snapshot)return;const s=snapshot.season;const ms=s.status==='paused'?s.remainingMs:s.endsAt?Math.max(0,Date.parse(s.endsAt)-(Date.now()+offset)):null;const minutes=ms===null?null:Math.ceil(ms/60000);text('#adminTime',s.status==='finished'||ms===0?'Конкурс завершён':(s.status==='paused'?'Пауза · ':'Идёт · ')+(minutes===null?'без срока':Math.floor(minutes/1440)+' д '+Math.floor(minutes%1440/60)+' ч '+minutes%60+' мин'));}
 function list(selector,items){const host=section.querySelector(selector);host.replaceChildren();for(const value of items){const p=document.createElement('p');p.textContent=value;host.append(p);}if(!items.length)host.textContent='Пока нет записей.';}
 function render(result){snapshot=result;offset=Date.parse(result.serverNow)-Date.now();clock();text('#adminContestId',result.season.id);text('#adminSummary','Участников: '+result.players+' · Полётов: '+result.flights);const body=$('#adminRanking');body.replaceChildren();for(const r of result.rows){const tr=document.createElement('tr');for(const v of [r.rank,r.nickname,r.playerId||'—',fmt(r.distance)+' м']){const td=document.createElement('td');td.textContent=v;tr.append(td);}body.append(tr);}if(!result.rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=4;td.textContent='Пока нет сохранённых конкурсных полётов.';tr.append(td);body.append(tr);}list('#adminHistory',result.history.map(r=>r.id+' · '+new Date(r.startsAt).toLocaleString('ru-RU')));list('#adminLog',result.log.map(r=>new Date(r.at).toLocaleString('ru-RU')+' · '+names[r.operation]));controls();}
 async function refresh(){if(busy)return;busy=true;controls();text('#adminStatus','Обновляем данные…');try{const response=await OrbitaCloud.adminRead();if(!response.season||!Number.isInteger(response.season.revision))throw new Error('Сервер вернул несовместимые данные. Нужна новая версия Backend.gs.');render(response);$('#adminStatus').dataset.error='false';text('#adminStatus',pending?'Есть неподтверждённая команда. Нажми «Повторить сохранение».':'Данные получены с сервера.');}catch(e){snapshot=null;text('#adminStatus',e.code==='UNKNOWN_ACTION'?'Опубликована старая версия сервера. Замени Backend.gs полным файлом и выбери «Новая версия» в существующем развертывании Apps Script. После этого нажми «Обновить».':e.message);$('#adminStatus').dataset.error='true';text('#adminTime','Нет подключения к управлению конкурсом');text('#adminSummary','Запуск недоступен, пока сервер не подтвердит доступ.');}finally{busy=false;controls();}}
 async function send(){if(busy||!pending)return;busy=true;controls();text('#adminStatus','Сохраняем изменение…');try{const result=await OrbitaCloud.adminCommand(pending);localStorage.removeItem(storageKey);pending=null;render(result);text('#adminStatus','Изменение сохранено.');loadRanking();}catch(e){if(['STALE_STATE','FORBIDDEN','INVALID_STATE','INVALID_RESULT','INVALID_ACTION','COMMAND_CONFLICT','UNKNOWN_ACTION'].includes(e.code)){localStorage.removeItem(storageKey);pending=null;}text('#adminStatus',e.message+(pending?' Повтори сохранение: время не будет добавлено дважды.':''));}finally{busy=false;controls();}}
 function execute(operation){if(busy||pending||!snapshot)return;const minutes=Number($('#adminMinutes').value)*Number($('#adminUnit').value);if(['new','set','add','subtract'].includes(operation)&&(!Number.isSafeInteger(minutes)||minutes<1||minutes>525600)){text('#adminStatus','Укажи целое число минут от 1 до 525600.');return;}const commit=()=>{const command={commandId:crypto.randomUUID(),revision:snapshot.season.revision,operation,minutes};try{localStorage.setItem(storageKey,JSON.stringify(command));}catch{text('#adminStatus','Не удалось сохранить команду на устройстве. Изменения не отправлены.');return;}pending=command;send();};if(['new','finish'].includes(operation)){showModal('<h2>'+names[operation]+'?</h2><p>'+ (operation==='new'?'Текущий конкурс будет закрыт. Новый топ начнётся с нуля. Длительность: '+minutes+' мин.':'Текущий топ будет зафиксирован. Новые полёты станут тренировочными.')+'</p><button class="primary" id="adminConfirm">Подтвердить</button>');$('#adminConfirm').onclick=()=>{closeModal();commit();};}else commit();}
 section.querySelectorAll('[data-admin]').forEach(b=>b.onclick=()=>execute(b.dataset.admin));$('#adminRefresh').onclick=refresh;$('#adminRetry').onclick=send;button.onclick=()=>{navigate('admin');refresh();};setInterval(()=>{if(!section.classList.contains('hidden'))clock();},1000);controls();
})();
